"use client";
import { useState } from "react";
import Image from "next/image";
import { motion } from "framer-motion";
import { FaChevronLeft, FaChevronRight, FaStar, FaShoppingCart } from "react-icons/fa";
import { useRouter } from "next/navigation";
import mongoose from "mongoose";
import { IProduct } from "@/models/product.model";


export default function UserProductCard({ product }: { product: IProduct }) {
  const router = useRouter()
  const images = [
    product.image1,
    product.image2,
    product.image3,
    product.image4,
  ];

  const openProduct = () => {
  router.push(`/view-product/${product._id}`);
};

  const [current, setCurrent] = useState(0);

  const next = () =>
    setCurrent((prev) => (prev + 1) % images.length);

  const prev = () =>
    setCurrent((prev) => (prev - 1 + images.length) % images.length);

  const handleAddToCart = () => {
    console.log("Added to cart:", product._id);
    // ✅ Yahan aap apna cart logic add kar sakte ho
  };

  return (
    <motion.div
      initial={{ opacity: 0, y: 60 }}
      whileInView={{ opacity: 1, y: 0 }}
      transition={{
        duration: 1,
        ease: [0.25, 0.1, 0.25, 1],
      }}
      viewport={{ once: true, amount: 0.2 }}
      whileHover={{ scale: 1.03 }}
      className="bg-white rounded-xl shadow-md overflow-hidden border hover:shadow-xl transition"
      onClick={openProduct}
    >
      {/* ================= IMAGE SLIDER ================= */}
      <div className="relative w-full h-52 overflow-hidden">
        <Image
          src={images[current]}
          alt={product.title}
          fill
          className="object-cover transition-all duration-200"
        />

        {/* LEFT */}
        <button
          onClick={prev}
          className="absolute left-2 top-1/2 -translate-y-1/2 bg-black/50 p-2 rounded-full text-white"
        >
          <FaChevronLeft size={14} />
        </button>

        {/* RIGHT */}
        <button
          onClick={next}
          className="absolute right-2 top-1/2 -translate-y-1/2 bg-black/50 p-2 rounded-full text-white"
        >
          <FaChevronRight size={14} />
        </button>

        {/* DOTS */}
        <div className="absolute bottom-2 left-1/2 -translate-x-1/2 flex gap-1">
          {images.map((_, i) => (
            <span
              key={i}
              className={`w-2 h-2 rounded-full ${
                current === i ? "bg-white" : "bg-white/50"
              }`}
            />
          ))}
        </div>
      </div>

      {/* ================= PRODUCT INFO ================= */}
      <div className="p-4 space-y-2">
        <h3 className="font-semibold text-sm line-clamp-1">
          {product.title}
        </h3>

        <p className="text-xs text-gray-500">
          {product.category}
        </p>

        <p className="font-bold text-lg text-green-600">
          ₹ {product.price}
        </p>

        {/* ⭐ REVIEWS */}
        <div className="flex items-center gap-1 text-yellow-500 text-sm">
          <FaStar />
          <span>{4.5}</span>
          <span className="text-gray-400 text-xs">(Reviews)</span>
        </div>

        {/* 🏪 VENDOR SHOP NAME */}
        <p className="text-xs text-gray-500">
          Sold by:{" "}
          <span className="font-medium text-gray-700">
            {product.vendor?.shopName || "Unknown Shop"}
          </span>
        </p>

        {/* ✅ ADD TO CART BUTTON */}
        <motion.button
          whileHover={{ scale: 1.05 }}
          whileTap={{ scale: 0.95 }}
          onClick={handleAddToCart}
          className="w-full mt-3 bg-black text-white py-2 rounded-lg flex items-center 
                     justify-center gap-2 hover:bg-gray-900 transition"
        >
          <FaShoppingCart size={14} />
          Add to Cart
        </motion.button>
      </div>
    </motion.div>
  );
}
