"use client";

import { useParams } from "next/navigation";
import Image from "next/image";
import { useSelector } from "react-redux";
import { RootState } from "@/redux/store";
import UserProductCard from "@/component/userProductCard";
import { motion } from "framer-motion";

export default function ShopDetailPage() {
  const { id } = useParams();

  const { allVendorData } = useSelector(
    (state: RootState) => state.vendor
  );

  // ✅ ✅ IMPORTANT: DATA NOT READY YET
  if (!allVendorData || allVendorData.length === 0) {
    return (
      <div className="min-h-screen flex items-center justify-center text-white bg-black">
        Loading shop details...
      </div>
    );
  }

  // ✅ FIND VENDOR (AFTER DATA EXISTS)
  const vendor = allVendorData.find(
    (v) => String(v._id) === String(id)
  );

  if (!vendor) {
    return (
      <div className="min-h-screen flex items-center justify-center text-white bg-black">
        Vendor Not Found
      </div>
    );
  }

  // ✅ ✅ GET PRODUCTS SAFELY
  const vendorProducts = vendor.vendorProducts || [];

  return (
    <div className="min-h-screen bg-gradient-to-br from-gray-900 via-black to-gray-900 text-white p-6">

      {/* ================== ✅ SHOP HEADER ================== */}
      <motion.div
        initial={{ opacity: 0, y: 50 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ duration: 0.6 }}
        className="max-w-6xl mx-auto mb-12 bg-white/10 backdrop-blur-xl p-6 rounded-2xl border border-white/20 grid md:grid-cols-2 gap-6 shadow-xl"
      >
        {/* ✅ IMAGE */}
        <div className="relative w-full h-60 overflow-hidden rounded-xl">
          <Image
            src={vendor.image || "/shop.png"}
            alt={vendor.shopName || "Shop"}
            fill
            className="object-cover"
            priority
          />
        </div>

        {/* ✅ DETAILS */}
        <div className="flex flex-col justify-center">
          <h1 className="text-3xl font-bold mb-3">
            {vendor.shopName}
          </h1>

          <p className="text-gray-300 mb-2">
            {vendor.businessAddress}
          </p>

          <p className="text-sm text-gray-400 mb-1">
            GST: {vendor.gstNumber || "Not Provided"}
          </p>

          <span
            className={`inline-block mt-2 w-fit px-4 py-1 rounded-full text-sm ${
              vendor.verificationStatus === "approved"
                ? "bg-green-600/20 text-green-400"
                : vendor.verificationStatus === "pending"
                ? "bg-yellow-600/20 text-yellow-400"
                : "bg-red-600/20 text-red-400"
            }`}
          >
            {vendor.verificationStatus}
          </span>
        </div>
      </motion.div>

      {/* ================== ✅ VENDOR PRODUCTS ================== */}
      <div className="max-w-6xl mx-auto">
        <h2 className="text-2xl font-bold mb-8">
          Products by {vendor.shopName}
        </h2>

        {vendorProducts.length === 0 ? (
          <p className="text-gray-400">
            No products added by this shop yet.
          </p>
        ) : (
          <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 gap-6">
            {vendorProducts.map((product: any, i: number) => (
              
                <UserProductCard key={String(product._id)} product={product} />
              
            ))}
          </div>
        )}
      </div>
    </div>
  );
}
